{
  "hypotheses": [
    {
      "stance": "bull",
      "mechanism": "若 UPS 隨最大客戶逐步減量而合併分揀班次及配送路線，相較減量後仍維持原網路，可少付閒置產能的成本。若當年節省超過重整費用，將支撐營業利益率。約 10 億美元是多年節省目標，2025 年淨節省額待查。",
      "target": "UPS",
      "horizon": "2026-03-31",
      "catalyst": "UPS 於 2025 年 1 月 30 日宣布重整美國網路。觀察 2025 年內流程調整進度，並於 2026 年 3 月 31 日前核對 UPS 全年業績公告。",
      "prediction": "UPS 2025 全年合併營業利益率按原指引口徑達 10.8% 或以上。以指引中心值作情境門檻，此合併指標只能檢驗獲利表現，網路重整的貢獻仍須看成本說明。",
      "invalidation": "截至 2026 年 3 月 31 日，UPS 公布的 2025 全年同口徑合併營業利益率低於 10.8%，即推翻此獲利預測。若公司另有節省，仍可能被其他成本抵銷。",
      "claim_ids": ["fact:ups-q4:network", "fact:ups-q4:volume", "fact:ups-q4:guidance"]
    },
    {
      "stance": "bear",
      "mechanism": "若最大客戶減量早於 UPS 編製指引時的假設，相較維持原承運量，UPS 完成的收費配送將減少。若其他客戶的包裹量或單件收入不足以填補缺口，全年營收可能低於指引中心值。客戶實際減量時程與單件收入均未揭露。",
      "target": "UPS",
      "horizon": "2026-03-31",
      "catalyst": "2025 年 1 月 30 日公布原則協議後，觀察減量是否已影響 2025 年配送業務，並於 2026 年 3 月 31 日前核對 UPS 全年業績公告。減量逾半的計畫期限在 2026 年下半年。",
      "prediction": "UPS 2025 全年合併營收低於原指引中心值 890 億美元。合併營收是淨影響的代理指標，須搭配 UPS 對美國業務包裹量的說明，才能判斷減量是否為原因。",
      "invalidation": "截至 2026 年 3 月 31 日，UPS 公布的 2025 全年合併營收達 890 億美元或以上，即推翻此營收預測，即使最大客戶已開始減量。",
      "claim_ids": ["fact:ups-q4:volume", "fact:ups-q4:guidance"]
    }
  ],
  "assessment": {
    "thesis": "UPS 在 2025 年的營運取決於兩個時程：最大客戶減量會減少配送收入，美國網路重整能否同步降低成本，則決定利益率可獲多少支撐。",
    "key_gap": "2025 年已實現的網路淨節省，能否抵銷已減少包裹的利益貢獻？若 UPS 未量化兩項影響，精確歸因需要非公開的客戶單件收益、配送成本及重整費用明細。",
    "next_check": "先查 2025 年內 UPS 季度業績公告對減量與網路調整的進度說明，再於 2026 年 3 月 31 日前查 2025 全年業績公告，按 2025 年 1 月 30 日原指引口徑核對合併營收與營業利益率。",
    "evidence_limits": [
      {"evidence_id": "ups-q4:guidance", "limit": "890 億美元營收與 10.8% 營業利益率均為 2025 全年合併指引約數。指引未列編製時假設的客戶減量幅度或當年節省額。"},
      {"evidence_id": "ups-q4:network", "limit": "公告確認美國網路重整計畫，約 10 億美元為多年節省目標。2025 年已實現節省、執行費用與淨利益均待揭露。"},
      {"evidence_id": "ups-q4:volume", "limit": "原則協議以 2026 年下半年減量逾半為目標，未提供 2025 年實際客戶件量。UPS 另披露 SurePost 自 2025 年 1 月 1 日起全數自行配送，這項營運變更也會影響網路負荷。"}
    ],
    "public_checks": [
      {"metric": "最大客戶減量進度，以及 UPS 是否因件量變化調整全年營收指引", "source_to_watch": "UPS 季度業績新聞稿及投資人說明", "window": "自原則協議公告後至 2025 年全年業績公布，最遲檢視至 2026 年 3 月 31 日", "impact_on_thesis": "若 UPS 明確將營收指引下修歸因於提前減量，則提高對看空路徑的信心。若僅確認已減量，只能確認機制啟動，仍無法量化收入損失。", "evidence_ids": ["ups-q4:volume", "ups-q4:guidance"]},
      {"metric": "美國配送網路流程調整的完成進度及已實現節省", "source_to_watch": "UPS 季度及全年業績新聞稿中的網路重整說明", "window": "自重整公告後的 2025 年各季至全年業績公布，最遲檢視至 2026 年 3 月 31 日", "impact_on_thesis": "若 UPS 說明哪些流程已調整，可確認執行進度。若進一步揭露當期節省高於執行費用，才支持當年淨獲利受益。僅重申多年目標，當年貢獻仍待查。", "evidence_ids": ["ups-q4:network"]}
    ],
    "supply_chain": [],
    "trade_opportunities": []
  }
}
